crc_bench.target:
uint32_t crc32_table_driven(const uint8_t *data, size_t len) {
    uint32_t crc = 0xFFFFFFFFu;
    for (size_t i = 0; i < len; i++) {
        crc = (crc >> 8) ^ crc32_table[(crc ^ data[i]) & 0xFFu];
    }
    return crc ^ 0xFFFFFFFFu;
}

int main(int argc, char **argv) {
    /* Benchmark harness: hashes every argument and prints the checksum. */
    for (int i = 1; i < argc; i++) {
        printf("%08X  %s\n", crc32_table_driven((const uint8_t *)argv[i], strlen(argv[i])), argv[i]);
    }
    return 0;
}

image_resize.target:
static void resize_nearest(Bitmap *dst, const Bitmap *src) {
    for (int y = 0; y < dst->h; y++) {
        for (int x = 0; x < dst->w; x++) {
            int sx = x * src->w / dst->w;
            int sy = y * src->h / dst->h;
            dst->px[y * dst->w + x] = src->px[sy * src->w + sx];
        }
    }
}
/* Batch image resizer: reads a folder, writes thumbnails. */

json_fmt.target:
int format_json(FILE *in, FILE *out) {
    int depth = 0, ch;
    while ((ch = fgetc(in)) != EOF) {
        if (ch == '{' || ch == '[') depth++;
        if (ch == '}' || ch == ']') depth--;
        fputc(ch, out);
    }
    return depth == 0 ? 0 : -1;
}
/* Command-line JSON pretty printer. */

